// §14.7 Resumen semanal, por correo a administracion.
//
// §14 lo titula «con IA» y aqui NO hay un nodo de LLM, a proposito: el
// principio del proyecto es que la logica de IA vive en Spring (§10, §14), y
// no existe un endpoint que resuma la operacion. /api/rag/preguntar responde
// solo con lo que hay en los documentos del reglamento, que no son estos
// numeros. Escribir aqui un prompt seria exactamente poner logica de IA en
// n8n, que es lo que el contrato prohibe.
//
// Si se quiere el resumen redactado por un modelo, lo que toca es un endpoint
// nuevo en Spring que use el LlmClient que ya existe, y que este flujo llame
// a ese endpoint. Mientras eso no exista, el resumen son las cifras.

const s = $json || {};
const t = s.tarjetas || {};
const p = s.paquetesPorAntiguedad || {};
const horas = Array.isArray(s.visitasPorHoraHoy) ? s.visitasPorHoraHoy : [];

let punta = 0;
for (let i = 1; i < horas.length; i++) {
  if (horas[i] > horas[punta]) {
    punta = i;
  }
}
const huboTrafico = horas.length > 0 && horas[punta] > 0;

const n = (v) => (v === null || v === undefined ? '-' : String(v));

const texto = [
  'Estado del conjunto a esta hora.',
  '',
  'AHORA MISMO',
  '  Personas dentro:             ' + n(t.personasDentro),
  '  Ingresos de hoy:             ' + n(t.ingresosHoy),
  '  Autorizaciones activas:      ' + n(t.autorizacionesActivas),
  '  Solicitudes pendientes:      ' + n(t.solicitudesPendientes),
  '',
  'PENDIENTES DE ATENCION',
  '  Paquetes sin retirar:        ' + n(t.paquetesPendientes),
  '    menos de 24 h:             ' + n(p.menosDe24Horas),
  '    entre 24 y 72 h:           ' + n(p.entre24Y72Horas),
  '    entre 72 h y 7 dias:       ' + n(p.entre72HorasY7Dias),
  '    mas de 7 dias (escalados): ' + n(p.masDe7Dias),
  '  Salidas no registradas:      ' + n(t.salidasNoRegistradas),
  '  Personas no permitidas:      ' + n(t.noPermitidosActivos),
  '',
  huboTrafico
    ? 'La hora de mas trafico hoy fue la de las ' + punta + ':00, con ' + horas[punta] + ' ingresos.'
    : 'Hoy todavia no se han registrado ingresos.',
  '',
  'Los paquetes de mas de 7 dias son exactamente los que ya se escalaron a',
  'administracion: si ese numero no baja de una semana a otra, hay un paquete',
  'que nadie esta reclamando.',
  '',
  'Solo cifras agregadas: este correo no lleva nombres de residentes ni de',
  'visitantes (§6).',
].join('\n');

return [{
  json: {
    destinatario: $env.CORREO_ADMINISTRACION || 'administracion@example.test',
    asunto: 'Resumen semanal de PorteriaYa',
    texto,
  },
}];
